/** Which paths the coding agent may change. Anything else routes to needs-human. */
const PROTECTED = [
  /^src\/api\/(auth|tokens)\.ts$/,
  /^src\/config\.ts$/,
  /^src\/runner\//,
  /^src\/worker\//,
  /^src\/adapters\//,
  /^src\/store\//,
];

export interface PolicyInput { path: string; kind: 'file' | 'symlink' | 'other'; existedBefore: boolean; deleted: boolean }

/** Generated by the runner itself after the agent run (see controller). */
const GENERATED = new Set(['contracts/openapi.json', 'contracts/mcp-tools.json']);

export function checkChange(c: PolicyInput): string | undefined {
  if (c.kind !== 'file' && !c.deleted) return `${c.path}: only regular files allowed`;
  if (GENERATED.has(c.path)) return c.deleted ? `${c.path}: generated file deleted` : undefined;
  if (c.path.includes('..') || c.path.startsWith('/') || c.path.includes('\\')) return `${c.path}: unsafe path`;
  if (/^(package(-lock)?\.json|tsconfig.*\.json|Dockerfile|docker\/|k8s\/|\.github\/|migrations\/)/.test(c.path)) {
    return `${c.path}: dependencies, configuration or infrastructure change`;
  }
  if (/^tests\//.test(c.path)) {
    if (c.existedBefore) return `${c.path}: existing tests are protected`;
    return /^tests\/[\w.-]+\.test\.ts$/.test(c.path) ? undefined : `${c.path}: new tests must be tests/*.test.ts`;
  }
  if (!/^src\/[\w/.-]+\.ts$/.test(c.path)) return `${c.path}: only TypeScript files under src/ may change`;
  if (PROTECTED.some((r) => r.test(c.path))) return `${c.path}: protected area`;
  if (c.deleted) return `${c.path}: deleting files is not allowed`;
  return undefined;
}

export function checkChanges(changes: PolicyInput[]): string[] {
  if (changes.length === 0) return ['no changes produced'];
  if (changes.length > 40) return ['too many changed files'];
  return changes.map(checkChange).filter((x): x is string => x !== undefined);
}
